import{_,o as e,c as t,ac as a}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第一次全体会议公报（第一号）","description":"","frontmatter":{"prev":{"text":"十二届一中全会简介","link":"./"},"next":{"text":"胡耀邦在党的十二届一中全会上的讲话","link":"./胡耀邦在党的十二届一中全会上的讲话"}},"headers":[],"relativePath":"12/1/中国共产党第十二届中央委员会第一次全体会议公报（第一号）.md","filePath":"12/1/中国共产党第十二届中央委员会第一次全体会议公报（第一号）.md"}'),r={name:"12/1/中国共产党第十二届中央委员会第一次全体会议公报（第一号）.md"};function n(o,p,s,i,c,l){return e(),t("div",null,[...p[0]||(p[0]=[a('<h1 id="中国共产党第十二届中央委员会第一次全体会议公报-第一号" tabindex="-1">中国共产党第十二届中央委员会第一次全体会议公报（第一号） <a class="header-anchor" href="#中国共产党第十二届中央委员会第一次全体会议公报-第一号" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第一次全体会议公报（第一号）&quot;">​</a></h1><p><em>（一九八二年九月十二日）</em></p><p>  中国共产党第十二届中央委员会第一次全体会议，1982年9月12日起在北京举行。会议由胡耀邦、赵紫阳同志主持。到会的中央委员210人，中央候补委员138人。中央顾问委员会委员149人和黄克诚同志列席了会议。全会第一天选举产生了中央政治局委员和中央政治局 候补委员、中央政治局常务委员会委员、中央委员会总书记、中央书记处书记和候补书记，决定了中央军事委员会主席、副主席。</p><p>  名单如下：</p><p>  （一）中央政治局委员、候补委员</p><p>  一、中央政治局委员（按姓氏笔划为序）</p><p>  万里 习仲勋 王震 韦国清（壮族）</p><p>  乌兰夫（蒙古族） 方毅 邓小平 邓颖超（女）</p><p>  叶剑英 李先念 李德生 杨尚昆</p><p>  杨得志 余秋里 宋任穷 张廷发</p><p>  陈云 赵紫阳 胡乔木 胡耀邦</p><p>  聂荣臻 倪志福 徐向前 彭真</p><p>  廖承志</p><p>  二、中央政治局候补委员（按得票多少为序）</p><p>  姚依林 秦基伟 陈慕华（女）</p><p>  （二）中央政治局常务委员会委员</p><p>  胡耀邦 叶剑英 邓小平 赵紫阳</p><p>  李先念 陈云</p><p>  （三）中央委员会总书记</p><p>  胡耀邦</p><p>  （四）中央书记处书记、候补书记</p><p>  一、书记（按姓氏笔划为序）</p><p>  万里 习仲勋 邓力群 杨勇</p><p>  余秋里 谷牧 陈丕显 胡启立</p><p>  姚依林</p><p>  二、候补书记（按得票多少为序）</p><p>  乔石 郝建秀（女）</p><p>  （五）中央军事委员会主席、副主席</p><p>  主席：邓小平</p><p>  副主席：叶剑英 徐向前 聂荣臻 杨尚昆（常务副主席）</p>',30)])])}const f=_(r,[["render",n]]);export{m as __pageData,f as default};
